route('post','/api/guest-start-batch',async req=>{cashRequired(req,'liberar visitantes');const input=guestInput(req.body);const ids=[...new Set((Array.isArray(req.body.stationIds)?req.body.stationIds:[]).map(String))];if(!ids.length)fail('Escolha pelo menos uma estação livre.');if(ids.length>200)fail('Muitas estações.');const results=[];for(const stationId of ids){let name=stationId;try{name=store.station(stationId).name;const r=await startGuest(stationId,input,actor(req));results.push({stationId,name,ok:true,sessionId:r.session.id,cents:r.sale.cents});}catch(e){results.push({stationId,name,ok:false,message:e.message});}}const ok=results.filter(r=>r.ok);store.log(actor(req),'visitantes-lote',`Visitantes em grupo: ${ok.length} liberado(s), ${results.length-ok.length} falha(s).`);return{total:results.length,success:ok.length,failed:results.length-ok.length,cents:ok.reduce((a,r)=>a+r.cents,0),results}});
route('post','/api/credit',async req=>{cashRequired(req,'adicionar tempo');const memberId=String(req.body.memberId);const m=store.member(memberId);if(!m.active)fail('Cliente inativo.');const creditQuote=store.quote(req.body);/* 3.0.50: pacote GRATIS (valor R$ 0,00): sem forma de pagamento; OBS e chave de autenticacao (senha do usuario logado no servidor) obrigatorias. */delete req.body.freeNote;delete req.body.authorizedBy;if(creditQuote.cents===0){const note=String(req.body.obs??'').trim();if(note.length<3)fail('Informe a OBS do pacote grátis (mínimo 3 caracteres).');if(note.length>300)fail('A OBS deve ter até 300 caracteres.');const key=typeof req.body.authPassword==='string'?req.body.authPassword:'';if(!key||!verify(key,req.operator.hash)){store.log(actor(req),'recarga','Pacote grátis recusado: chave de autenticação incorreta ('+m.name+')');fail('Chave de autenticação incorreta. Use a senha do usuário logado no servidor.');}req.body.paymentMethod=undefined;delete req.body.payments;req.body.freeNote=note;req.body.authorizedBy=req.operator.username;}else if(require('./payments').wants(req.body))require('./payments').combined(req.body.payments,creditQuote.cents,require('./payments').RECHARGE);else require("./balance").payment(req.body.paymentMethod);delete req.body.authPassword;let station;if(req.body.stationId){station=store.station(String(req.body.stationId));if(pc.isAdmin(station.id))fail('Encerre o acesso administrativo deste PC antes de iniciar uma sessão.');if(!station.active||store.activeForStation(station.id)||store.activeForMember(memberId))fail('Escolha uma estação livre e um cliente sem sessão ativa.');if(station.kind==='computer'&&(!station.pcTokenHash||!pc.connected(station.id)))fail('Conecte o cliente deste computador antes de iniciar.');if(station.kind==='tv')await client(station).hdmi()}if(station&&(store.activeForMember(memberId)||store.activeForStation(station.id)))fail('A estação ou o cliente iniciou outra sessão. Confira antes de recarregar.');const sale=store.credit(memberId,req.body,actor(req));if(sale.free)store.log(actor(req),'recarga',`Pacote grátis autorizado por ${sale.authorizedBy}: ${m.name} • ${sale.label} • OBS: ${sale.freeNote}`);if(station)store.start(station.id,memberId,actor(req));return sale});
 route('post','/api/start',async req=>{const station=store.station(String(req.body.stationId)),m=store.member(String(req.body.memberId));if(pc.isAdmin(station.id))fail('Encerre o acesso administrativo deste PC antes de iniciar uma sessão.');if(!station.active||!m.active||store.activeForStation(station.id)||store.activeForMember(m.id)||m.creditSeconds<=0)fail('Confira estação livre, cliente ativo e saldo disponível.');if(station.kind==='computer'&&(!station.pcTokenHash||!pc.connected(station.id)))fail('Configure e conecte o cliente antes de iniciar.');if(station.kind==='tv')await client(station).hdmi();return store.start(station.id,m.id,actor(req))});
