 route('post','/api/stations',req=>{admin(req);const name=text(req.body.name,'Nome');const kind=['tv','computer'].includes(req.body.kind)?req.body.kind:fail('Tipo inválido.');const ip=String(req.body.ip||'').trim();if(ip&&!net.isIP(ip))fail('IP inválido.');if(kind==='tv'&&!ip)fail('Informe o IP da TV.');const hdmi=integer(req.body.hdmi||1,1,4,'HDMI');const brand=String(req.body.brand||'').toLowerCase();if(brand&&!/^[a-z0-9]{2,16}$/.test(brand))fail('Marca inválida.');const tvType=req.body.tvType==='android'?'android':'vidaa';return store.change(actor(req),'estacao','Estação configurada: '+name,()=>{let s=req.body.id?store.station(req.body.id):{id:id()};if(s.removedAt)fail('Computador removido. Configure novamente o cliente e autorize como novo computador.');if(store.activeForStation(s.id))fail('Encerre a sessão antes de alterar a estação.');if(!req.body.id)store.state.stations.push(s);clients.get(s.id)?.disconnect();clients.delete(s.id);Object.assign(s,{name,kind,ip,hdmi,brand,tvType,active:req.body.active!==false});return s})});
