 route('post','/api/report',async req=>{const s=store.state.sessions.find(s=>s.id===req.body.sessionId&&s.status==='finished');if(!s)fail('Sessão não encontrada.');if(store.activeForStation(s.stationId))fail('A estação está em uso. Encerre a sessão atual antes de exibir um resumo anterior.');await display(s)});
 route('post','/api/pairing/import',req=>{admin(req);const station=store.station(String(req.body.stationId));if(station.tvType==='android')fail('TV Android não usa arquivo de pareamento: use Parear TV.');if(store.activeForStation(station.id))fail('Encerre a sessão primeiro.');const data=req.body.data;if(!data||typeof data.uuid!=='string'||!/^([a-f0-9]{2}:){5}[a-f0-9]{2}$/i.test(data.uuid))fail('Arquivo de pareamento inválido.');const allowed=['uuid','detectedBrand','brand','token','clientId','username','profile','expires'];const clean={};for(const field of allowed){const value=data[field];if(value!==undefined){if(field==='expires'){if(!Number.isFinite(value))fail('Validade inválida.')}else if(typeof value!=='string'||value.length>8192)fail('Arquivo inválido.');clean[field]=value}}clients.get(station.id)?.disconnect();clients.delete(station.id);const dir=path.join(directory,'pairing');fs.mkdirSync(dir,{recursive:true});const file=path.join(dir,`tv-${station.id}.json`);if(fs.existsSync(file))fs.copyFileSync(file,file+'.previous');fs.writeFileSync(file,JSON.stringify(clean,null,2));store.log(actor(req),'tv','Pareamento importado: '+station.name);});
 route('post','/api/machine-settings',req=>{admin(req);const next={};for(const key of ['taskManager','controlPanel','securityOptions','dateTime']){if(typeof req.body[key]!=='boolean')fail('Marque ou desmarque todas as opções.');next[key]=req.body[key]}/* 1.0.5: Painel de Controle e tela Ctrl+Alt+Del retirados (sempre desligados) */next.controlPanel=false;next.securityOptions=false;next.revision=(store.state.settings.machinePolicy.revision||0)+1;store.change(actor(req),'config','Restrições globais dos computadores atualizadas: '+JSON.stringify(next),()=>{store.state.settings.machinePolicy=next});return next});
 /* 1.0.5: valor da hora só muda com a senha do administrador; endereço aceita IP da rede (cabo/Wi-Fi) ou domínio (servidor em nuvem); campos ausentes mantêm o valor atual */
 const serverAddress=v=>{let url;try{url=new URL(String(v??'').trim())}catch{fail('Endereço inválido. Use http://IP-DO-SERVIDOR:3000.')}if(!['http:','https:'].includes(url.protocol)||url.username||url.password)fail('Use http://IP-DO-SERVIDOR:3000 ou, para servidor em nuvem, https://seu-dominio.');const host=url.hostname.replace(/^\[|\]$/g,'');if(net.isIP(host)){if(host.startsWith('127.')||['0.0.0.0','::1','::'].includes(host))fail('Use o IP da rede (cabo ou Wi-Fi), acessível pelas TVs e PCs — não 127.0.0.1.')}else if(host==='localhost'||!/^(?=.{1,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/i.test(host))fail('Use http://IP-DO-SERVIDOR:3000 ou, para servidor em nuvem, o domínio (ex.: https://gamezoney.exemplo.com.br).');return url.origin};
 route('get','/api/network',req=>{admin(req);return {interfaces:netinfo.interfaces(),port:netinfo.port(),machineTimeZone:netinfo.timeZone(),serverUrl:store.state.settings.serverUrl}});
 /* 1.0.5: "Atualizar Automático" (Configuração › Servidor IP): usa o IP atual desta máquina se o configurado não pertence mais a ela, confere as portas 3000/3443/3444 e as regras do Firewall do Windows (recria pelo firewall.ps1 se faltarem). */
 const probe=(host,port)=>new Promise(resolve=>{const c=net.connect({host,port,timeout:1500});const end=ok=>{c.destroy();resolve(ok)};c.once('connect',()=>end(true));c.once('timeout',()=>end(false));c.once('error',()=>end(false))});
 const ps=(command,timeout)=>new Promise(resolve=>require('child_process').execFile(path.join(process.env.SystemRoot||'C:\\Windows','System32','WindowsPowerShell','v1.0','powershell.exe'),['-NoProfile','-NonInteractive','-ExecutionPolicy','Bypass','-Command',command],{windowsHide:true,timeout,cwd:__dirname},(e,out)=>resolve({ok:!e,out:String(out||'').trim(),code:e?.code})));
 const quote=s=>"'"+String(s).replace(/'/g,"''")+"'";
 const missingFirewall=async()=>{const r=await ps(`. ${quote(path.join(__dirname,'firewall-rules.ps1'))}; $m=@(Get-GzFirewallPlan -Role server -InstallDirectory ${quote(__dirname)} | Where-Object { $r=Get-NetFirewallRule -PolicyStore PersistentStore -Name $_.Name -ErrorAction SilentlyContinue; -not $r -or [string]$r.Enabled -ne 'True' } | ForEach-Object { $_.Name }); 'MISSING:'+($m -join ',')`,30000);const line=r.out.split(/\r?\n/).find(l=>l.startsWith('MISSING:'));return line===undefined?null:line.slice(8).split(',').filter(Boolean)};
 async function autoNetwork(actorName){const checks=[],s=store.state.settings,list=netinfo.interfaces(),real=list.filter(i=>i.kind!=='virtual');let cur;try{cur=new URL(s.serverUrl)}catch{}
  const tz=netinfo.timeZone();if(tz&&tz!==s.timeZone)store.change(actorName,'config','Horário ajustado ao do computador do servidor ('+tz+')',()=>{store.state.settings.timeZone=tz});
  /* 1.0.5: endereço em nuvem (domínio) é mantido; confere se responde. */
  if(cur&&!net.isIP(cur.hostname.replace(/^\[|\]$/g,''))){const port=Number(cur.port)||(cur.protocol==='https:'?443:80);let ips=[];try{ips=(await require('dns').promises.lookup(cur.hostname,{all:true})).map(a=>a.address)}catch{}checks.push({name:'Endereço em nuvem',ok:ips.length>0,detail:ips.length?`${cur.hostname} → ${ips.join(', ')}`:`${cur.hostname} não foi encontrado (DNS)`});checks.push({name:'Conexão em nuvem',ok:ips.length>0&&await probe(cur.hostname,port),detail:'servidor em nuvem respondendo'});
   if(list.length){const lp=server.address()?.port||netinfo.port(),pick=real[0]||list[0];checks.push({name:'Conexão na rede local',ok:await probe(pick.address,lp),detail:`este servidor também responde na rede local (${pick.address})`})}
   checks.push({name:'Data e hora',ok:true,detail:new Date().toLocaleString('pt-BR',{timeZone:store.state.settings.timeZone,dateStyle:'short',timeStyle:'short'})+' (as do computador do servidor)'});const ok=checks.every(c=>c.ok);
   store.log(actorName,'config','Atualizar Automático (nuvem): '+checks.map(c=>(c.ok?'OK ':'FALHA ')+c.name).join(' • '));return {serverUrl:s.serverUrl,changed:false,mode:'cloud',available:ok,checks}}
  if(!list.length)fail('Nenhuma rede ativa nesta máquina. Confira o cabo ou o Wi-Fi.');const port=server.address()?.port||netinfo.port();const mine=cur&&list.find(i=>i.address===cur.hostname);const pick=mine||(real[0]||list[0]);const url=`http://${pick.address}:${port}`;const changed=url!==s.serverUrl;
  if(changed)store.change(actorName,'config','Atualizar Automático: endereço do servidor '+s.serverUrl+' → '+url,()=>{store.state.settings.serverUrl=url});
  checks.push({name:'IP do servidor',ok:true,detail:`${pick.address} (${{cabo:'cabo de rede',wifi:'Wi-Fi',virtual:'adaptador virtual'}[pick.kind]} • ${pick.name})${changed?' — atualizado':' — já estava correto'}`});
  checks.push({name:'Conexão das TVs',ok:await probe(pick.address,port),detail:'servidor respondendo neste IP'});
  const pcPort=pcServer?.listening?pcServer.address().port:null;checks.push({name:'Conexão dos PCs',ok:!!pcPort&&await probe(pick.address,pcPort),detail:pcPort?'canal dos PCs respondendo neste IP':'canal HTTPS dos PCs não iniciou'});
  checks.push({name:'Busca dos PCs na rede',ok:discovery.running(),detail:discovery.running()?'busca na rede ativa — os PCs encontram o servidor no novo IP sozinhos':'busca na rede não iniciou'});
  if(process.platform!=='win32')checks.push({name:'Firewall do Windows',ok:true,detail:'não verificado (somente no Windows)'});
  else{let miss=await missingFirewall();if(miss===null)checks.push({name:'Firewall do Windows',ok:false,detail:'não foi possível ler as regras. Use o atalho "Reparar conexao de rede".'});else{let fixed=false;if(miss.length){await ps(`& ${quote(path.join(__dirname,'firewall.ps1'))} -Role server -Action Install; exit $LASTEXITCODE`,180000);fixed=true;miss=await missingFirewall()}const ok=Array.isArray(miss)&&!miss.length;checks.push({name:'Firewall do Windows',ok,detail:ok?(fixed?'regras recriadas — portas liberadas na rede local':'regras do GameZoney ativas'):'faltam regras. Aceite o aviso do Windows (administrador) ou use o atalho "Reparar conexao de rede".'})}}
  checks.push({name:'Data e hora',ok:true,detail:new Date().toLocaleString('pt-BR',{timeZone:store.state.settings.timeZone,dateStyle:'short',timeStyle:'short'})+' (as do computador do servidor)'});
  store.log(actorName,'config','Atualizar Automático (rede local): '+checks.map(c=>(c.ok?'OK ':'FALHA ')+c.name).join(' • '));return {serverUrl:url,changed,mode:'local',available:checks.every(c=>c.ok),checks}}
 route('post','/api/network/auto',async req=>{admin(req);return autoNetwork(actor(req))});
 route('post','/api/settings',req=>{admin(req);const s=store.state.settings;const cents=req.body.hourCents===undefined?s.hourCents:integer(req.body.hourCents,0,1000000,'Preço por hora');const priceChanged=cents!==s.hourCents;if(priceChanged){const key=typeof req.body.authPassword==='string'?req.body.authPassword:'';if(!key||!verify(key,req.operator.hash)){store.log(actor(req),'config','Alteração do valor da hora recusada: senha de administrador incorreta');fail('Senha de administrador incorreta.')}}const serverUrl=req.body.serverUrl===undefined?s.serverUrl:serverAddress(req.body.serverUrl);const timeZone=req.body.timeZone===undefined?s.timeZone:String(req.body.timeZone);try{new Intl.DateTimeFormat('pt-BR',{timeZone}).format()}catch{fail('Fuso horário inválido.')};const brl=c=>'R$ '+(c/100).toFixed(2).replace('.',',');const parts=[];if(priceChanged)parts.push('Valor da hora: '+brl(s.hourCents)+' → '+brl(cents));if(serverUrl!==s.serverUrl)parts.push('Endereço do servidor: '+serverUrl);if(timeZone!==s.timeZone)parts.push('Fuso: '+timeZone);if(!parts.length)return {ok:true,unchanged:true};store.change(actor(req),'config',parts.join(' • '),()=>Object.assign(store.state.settings,{hourCents:cents,serverUrl,timeZone}));return {ok:true}});
