 route('post','/api/operators',req=>{admin(req);const username=text(req.body.username,'Usuário',40);if(store.state.operators.some(o=>o.username.toLowerCase()===username.toLowerCase()))fail('Usuário já existe.');const role=req.body.role==='admin'?'admin':'operator',hash=passwordHash(req.body.password);store.change(actor(req),'operador',(role==='admin'?'Administrador':'Operador')+' criado: '+username,()=>store.state.operators.push({id:id(),username,hash,role,active:true,createdAt:Date.now(),createdBy:actor(req)}));});
