 /* 1.0.5: Ações dos PCs > Enviar Mensagem (PC específico ou todos). Texto entre *asteriscos* sai em dourado. */
 route('post','/api/pc/message',req=>{admin(req);const text=String(req.body.text??'').replace(/\r/g,'').trim();if(!text)fail('Escreva a mensagem.');if(text.length>200)fail('A mensagem pode ter até 200 caracteres.');const seconds=integer(req.body.seconds,3,3600,'Tempo na tela (segundos)');const scope=req.body.scope==='one'?'one':'all';const computers=store.state.stations.filter(s=>s.kind==='computer'&&!s.removedAt&&s.active);let targets=computers;if(scope==='one'){const s=store.station(String(req.body.stationId||''));if(s.kind!=='computer'||s.removedAt||!s.active)fail('Escolha um computador ativo.');targets=[s]}if(!targets.length)fail('Nenhum computador cadastrado.');const results=targets.map(s=>{const online=pc.connected(s.id);if(online)pc.sendMessage(s.id,text,seconds);return {stationId:s.id,name:s.name,ok:online,message:online?'Mensagem enviada.':'Computador sem conexão (não recebeu).'}});store.log(actor(req),'mensagem-pcs',`Mensagem (${seconds}s) para ${scope==='one'?targets[0].name:'todos os PCs'}: ${text}`);return {results,success:results.filter(r=>r.ok).length,failed:results.filter(r=>!r.ok).length}});
 route('post','/api/pc/actions',req=>{admin(req);const action=String(req.body.action||''),scope=String(req.body.scope||'');if(!['admin','finish','shutdown','restart'].includes(action))fail('Ação inválida.');if(!['all','available','one'].includes(scope))fail('Escopo inválido.');if(action==='finish'&&scope==='available')fail('Encerramento de sessão só pode ser aplicado às máquinas em uso.');const computers=store.state.stations.filter(s=>s.kind==='computer'&&!s.removedAt&&s.active);let targets;if(scope==='one'){const station=store.station(String(req.body.stationId||''));if(station.kind!=='computer'||station.removedAt||!station.active)fail('Escolha um computador ativo.');targets=[station];}else if(scope==='available'){targets=computers.filter(s=>!store.activeForStation(s.id));}else if(action==='finish'){targets=computers.filter(s=>!!store.activeForStation(s.id));}else targets=computers;const results=[];for(const station of targets){try{if(action==='finish'){const session=store.activeForStation(station.id);if(!session){results.push({stationId:station.id,name:station.name,ok:true,skipped:true,message:'Sem sessão ativa.'});continue;}store.finish(station.id,actor(req),'encerrado pela recepção');results.push({stationId:station.id,name:station.name,ok:true,message:'Sessão encerrada e saldo restante devolvido.'});continue;}if(!pc.connected(station.id))throw new Error('Computador sem conexão.');if(action==='admin'){if(pc.isAdmin(station.id)){results.push({stationId:station.id,name:station.name,ok:true,skipped:true,message:'Já está em modo administrador.'});continue;}pc.remote.command({stationId:station.id,type:'admin'},actor(req));results.push({stationId:station.id,name:station.name,ok:true,message:store.activeForStation(station.id)?'Liberação enviada. O tempo restante do cliente vai para o saldo e o PC entra em ADMIN sem fechar o jogo/área de trabalho.':'Liberação para modo administrador enviada.'});continue;}pc.remote.command({stationId:station.id,type:action},actor(req));results.push({stationId:station.id,name:station.name,ok:true,message:(action==='shutdown'?'Desligamento':'Reinício')+' enviado.'});}catch(error){results.push({stationId:station.id,name:station.name,ok:false,message:error.message});}}store.log(actor(req),'computadores-lote',`${action}/${scope}: ${results.filter(r=>r.ok).length} sucesso(s), ${results.filter(r=>!r.ok).length} falha(s)`);return{action,scope,total:results.length,success:results.filter(r=>r.ok&&!r.skipped).length,skipped:results.filter(r=>r.skipped).length,failed:results.filter(r=>!r.ok).length,results}});
 route('get','/api/pc/remote',req=>{admin(req);if(pc.isAdmin(String(req.query.stationId)))fail('Computador em manutenção.');return pc.remote.view(String(req.query.stationId),req.query.renew==='1')});
